    if constexpr (std::is_same_v<Input,std::uint8_t>)
        if (spec.transfer == 1) lookup = detail::srgb_decode_table().data();
    R matrix[9];
    for (int j = 0; j < 9; ++j) matrix[j] = V::set(T(spec.matrix[j]));
    std::size_t i = 0;
